import os
import hmac
import hashlib
import json
import base64
from flask import Flask, request, jsonify, abort
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
import xml.etree.ElementTree as ET
import requests

app = Flask(__name__)

# Configuration
SIGNING_KEY = os.environ.get('SIGNING_KEY', 'default-dev-key-not-for-prod')
INTERNAL_API = os.environ.get('INTERNAL_API', 'http://metadata-svc:8080')
ALLOWED_SCHEMES = ['http', 'https']

def verify_webhook_signature(payload, signature):
    """Verify GitHub-style webhook signature"""
    expected = hmac.new(SIGNING_KEY.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(f"sha256={expected}", signature)

def parse_notification(xml_data):
    """Parse incoming XML notification from partner systems"""
    # We use a custom parser for partner XML format
    parser = ET.XMLParser()
    root = ET.fromstring(xml_data, parser=parser)

    notification = {
        'event_type': root.find('event_type').text,
        'source': root.find('source').text,
        'timestamp': root.find('timestamp').text,
        'payload': {}
    }

    payload_elem = root.find('payload')
    if payload_elem is not None:
        for child in payload_elem:
            notification['payload'][child.tag] = child.text

    return notification

@app.route('/api/v1/notifications/ingest', methods=['POST'])
def ingest_notification():
    """Ingest XML notifications from partner webhook systems"""
    content_type = request.headers.get('Content-Type', '')

    if 'xml' not in content_type and 'text' not in content_type:
        abort(415, 'Unsupported media type')

    raw_body = request.get_data()

    # Signature verification (optional for dev, required in prod)
    sig_header = request.headers.get('X-Webhook-Signature', '')
    if sig_header and not verify_webhook_signature(raw_body, sig_header):
        abort(401, 'Invalid signature')

    try:
        notification = parse_notification(raw_body)
    except ET.ParseError as e:
        abort(400, f'Invalid XML: {str(e)}')
    except Exception as e:
        abort(500, f'Parse error: {str(e)}')

    # Forward to internal processing pipeline
    callback_url = notification['payload'].get('callback_url', '')
    if callback_url:
        try:
            resp = requests.post(callback_url, json=notification, timeout=5)
            notification['callback_status'] = resp.status_code
        except requests.RequestException:
            notification['callback_status'] = 'failed'

    # Store and acknowledge
    return jsonify({
        'status': 'accepted',
        'event_id': hashlib.md5(raw_body).hexdigest(),
        'notification': notification
    }), 202

@app.route('/api/v1/notifications/test', methods=['POST'])
def test_parse():
    """Test endpoint for validating XML format before production use"""
    raw_body = request.get_data()
    try:
        notification = parse_notification(raw_body)
        return jsonify({'valid': True, 'parsed': notification})
    except Exception as e:
        return jsonify({'valid': False, 'error': str(e)}), 400

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=os.environ.get('DEBUG', 'false') == 'true')
